#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define THREAD_PRIORITY K_PRIO_PREEMPT(10)

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;

static K_TIMER_DEFINE(test_timer, NULL, NULL);

static volatile int timer_expiry_count;
static volatile int timer_stop_count;

static void timer_expiry_fn(struct k_timer *timer)
{
	timer_expiry_count++;
}

static void timer_stop_fn(struct k_timer *timer)
{
	timer_stop_count++;
}

ZTEST_DMEM volatile int timer_user_data;

static void timer_user_data_expiry_fn(struct k_timer *timer)
{
	volatile int *data = (volatile int *)timer->user_data;

	*data = 1;
}

static void timer_user_data_stop_fn(struct k_timer *timer)
{
	volatile int *data = (volatile int *)timer->user_data;

	*data = 2;
}

/**
 * @brief Test k_timer_init
 *
 * @details Test timer initialization with expiry and stop functions.
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_init)
{
	k_timer_init(&test_timer, timer_expiry_fn, timer_stop_fn);

	zassert_equal(test_timer.expiry_fn, timer_expiry_fn, "Expiry function not set");
	zassert_equal(test_timer.stop_fn, timer_stop_fn, "Stop function not set");
}

/**
 * @brief Test k_timer_start and k_timer_stop
 *
 * @details Test starting and stopping a timer.
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_start_stop)
{
	k_timer_init(&test_timer, timer_expiry_fn, timer_stop_fn);

	timer_expiry_count = 0;
	timer_stop_count = 0;

	k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
	k_sleep(K_MSEC(5));
	k_timer_stop(&test_timer);

	zassert_equal(timer_expiry_count, 0, "Timer expired unexpectedly");
	zassert_equal(timer_stop_count, 1, "Stop function not called");

	timer_expiry_count = 0;
	timer_stop_count = 0;

	k_timer_start(&test_timer, K_MSEC(10), K_MSEC(10));
	k_sleep(K_MSEC(15));
	k_timer_stop(&test_timer);

	zassert_equal(timer_expiry_count, 1, "Timer did not expire");
	zassert_equal(timer_stop_count, 1, "Stop function not called");
}

/**
 * @brief Test k_timer_status_get
 *
 * @details Test getting timer status.
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_status_get)
{
	k_timer_init(&test_timer, timer_expiry_fn, timer_stop_fn);

	timer_expiry_count = 0;

	k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
	k_sleep(K_MSEC(5));
	zassert_equal(k_timer_status_get(&test_timer), 0, "Timer status incorrect");
	k_timer_stop(&test_timer);

	k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
	k_sleep(K_MSEC(15));
	zassert_equal(k_timer_status_get(&test_timer), 1, "Timer status incorrect");
	k_timer_stop(&test_timer);
}

/**
 * @brief Test k_timer_remaining_get
 *
 * @details Test getting remaining time on a timer.
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_remaining_get)
{
	k_timer_init(&test_timer, timer_expiry_fn, timer_stop_fn);

	k_timer_start(&test_timer, K_MSEC(100), K_NO_WAIT);
	k_busy_wait(10000);
	/* Remaining time should be around 90ms */
	zassert_true(k_timer_remaining_get(&test_timer) > K_MSEC(80).ticks, "Remaining time incorrect");
	zassert_true(k_timer_remaining_get(&test_timer) < K_MSEC(100).ticks, "Remaining time incorrect");
	k_timer_stop(&test_timer);
}

/**
 * @brief Test k_timer_user_data_set and k_timer_user_data_get
 *
 * @details Test setting and getting user data for a timer.
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_user_data)
{
	k_timer_init(&test_timer, timer_user_data_expiry_fn, timer_user_data_stop_fn);

	k_timer_user_data_set(&test_timer, (void *)&timer_user_data);
	zassert_equal(k_timer_user_data_get(&test_timer), (void *)&timer_user_data, "User data not set");

	timer_user_data = 0;
	k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
	k_sleep(K_MSEC(5));
	k_timer_stop(&test_timer);
	zassert_equal(timer_user_data, 2, "User data not updated by stop function");

	timer_user_data = 0;
	k_timer_start(&test_timer, K_MSEC(10), K_MSEC(10));
	k_sleep(K_MSEC(15));
	k_timer_stop(&test_timer);
	zassert_equal(timer_user_data, 1, "User data not updated by expiry function");
}

/**
 * @brief Test k_timer_is_active
 *
 * @details Test checking if a timer is active.
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_is_active)
{
	k_timer_init(&test_timer, NULL, NULL);

	zassert_false(k_timer_is_active(&test_timer), "Timer should not be active");

	k_timer_start(&test_timer, K_MSEC(100), K_NO_WAIT);
	zassert_true(k_timer_is_active(&test_timer), "Timer should be active");

	k_timer_stop(&test_timer);
	zassert_false(k_timer_is_active(&test_timer), "Timer should not be active");
}

/**
 * @brief Test k_timer_remaining_get_32
 *
 * @details Test getting remaining time on a timer (32-bit).
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_remaining_get_32)
{
	k_timer_init(&test_timer, timer_expiry_fn, timer_stop_fn);

	k_timer_start(&test_timer, K_MSEC(100), K_NO_WAIT);
	k_busy_wait(10000);
	/* Remaining time should be around 90ms */
	zassert_true(k_timer_remaining_get_32(&test_timer) > K_MSEC(80).ticks, "Remaining time incorrect");
	zassert_true(k_timer_remaining_get_32(&test_timer) < K_MSEC(100).ticks, "Remaining time incorrect");
	k_timer_stop(&test_timer);
}

/**
 * @brief Test k_timer_status_get_32
 *
 * @details Test getting timer status (32-bit).
 *
 * @ingroup kernel_timer_tests
 */
ZTEST(timer_api, test_timer_status_get_32)
{
	k_timer_init(&test_timer, timer_expiry_fn, timer_stop_fn);

	timer_expiry_count = 0;

	k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
	k_sleep(K_MSEC(5));
	zassert_equal(k_timer_status_get_32(&test_timer), 0, "Timer status incorrect");
	k_timer_stop(&test_timer);

	k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
	k_sleep(K_MSEC(15));
	zassert_equal(k_timer_status_get_32(&test_timer), 1, "Timer status incorrect");
	k_timer_stop(&test_timer);
}

ZTEST_SUITE(timer_api, NULL, NULL, NULL, NULL, NULL);
